    #[test]
    fn child_complete_actual_authored_typed_source_static_metadata_physical_scaffold(){
        use semio_framework_value::NativeEncodeControl;
        let mutation=crate::test_app_mutation_fixture::TestMutation::from(crate::test_app_mutation_fixture::SetLabel{value:"x".repeat(8194)});let pointer=match &mutation{crate::test_app_mutation_fixture::TestMutation::SetLabel(value)=>value.value.as_ptr(),_=>unreachable!()};
        let(mut capsule,construction)=semio_framework_trace::observe_heap_allocations_on_this_thread(||mutation.retained_pack_operation());assert_eq!((construction.requested_bytes,construction.released_bytes),(0,0));assert!(!construction.overflowed);
        let mut options=semio_framework_os_kernel::os_pack::codec::PackEncodeOptions::default();options.limits.max_file_len=8202;let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let mut measurement=semio_framework_os_kernel::os_spr::operation_bytes::OperationByteMeasurement::new(8202);
        let(result,encoding)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.scoped_maximum(512,|control|semio_framework_os_kernel::variants_binary::encode_op_into(&mut capsule,&options,&mut measurement,control)));result.unwrap();assert_eq!(measurement.exact_length().unwrap(),8202);assert_eq!((encoding.requested_bytes,encoding.released_bytes,capsule.allocated_bytes(),control.owned_bytes()),(0,0,0,0));assert!(!encoding.overflowed);
        let(zero,observed)=semio_framework_trace::observe_heap_allocations_on_this_thread(||capsule.retire_one(0,4096).unwrap());assert_eq!(zero,(false,0,0));assert_eq!((observed.requested_bytes,observed.released_bytes),(0,0));
        for _ in 0..8194+128{let(step,observed)=semio_framework_trace::observe_heap_allocations_on_this_thread(||capsule.retire_one(1,4096).unwrap());assert_eq!(observed.requested_bytes,0);assert_eq!(observed.released_bytes,step.2);assert!(observed.largest_release_bytes<=4096&&step.1<=1);assert!(!observed.overflowed);if !step.0{break}}
        assert_eq!(capsule.allocated_bytes(),0);assert!(capsule.variant_identity().is_err());let(_,dropped)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(capsule));assert_eq!((dropped.requested_bytes,dropped.released_bytes),(0,0));assert_eq!(match &mutation{crate::test_app_mutation_fixture::TestMutation::SetLabel(value)=>value.value.as_ptr(),_=>unreachable!()},pointer);
        eprintln!("[DEBUG] actual authored static metadata+embedded symbol/index source scaffold requests0/releases0 through constructor, original512 measurement, explicit1/4096 settlement and final capsule drop; caller8194 source remains separately retained");
    }
